"""Fuzz the campaign pattern grammar against an independent Python-re oracle."""
import random, re as pyre, sys
sys.path.insert(0,'/workspace/project/src')
from eywa.regex import compile_pattern, parse

random.seed(1234)

LITERALS = list("abcxyz019.-_ \t") + ["\\|","\\*","\\(","\\)","\\[","\\]", "\\\\"]

def gen_atom(depth=0):
    kind = random.random()
    if kind < 0.45:
        return random.choice(LITERALS)
    if kind < 0.7 and depth < 2:
        return '(' + gen_union(depth+1) + ')'
    # character class
    items = []
    for _ in range(random.randint(1,3)):
        if random.random() < 0.4:
            lo = random.choice("abcxyz019")
            hi = chr(ord(lo)+random.randint(0,3))
            items.append(lo+'-'+hi)
        else:
            items.append(random.choice(["a","z","0","9","\\-","\\]","\\\\","\\[","\\*","\\|","\\("]))
    return '[' + ''.join(items) + ']'

def gen_seq(depth=0):
    out=[]
    for _ in range(random.randint(0,3)):
        a = gen_atom(depth)
        if random.random()<0.3: a += '*'
        if random.random()<0.1: a += '**'
        out.append(a)
    return ''.join(out)

def gen_union(depth=0):
    return '|'.join(gen_seq(depth) for _ in range(random.randint(1,3)))

def gen_pattern():
    p = gen_union()
    if random.random()<0.1: p = ''
    return p

# ---- independent translation to Python re
def class_char(s, i):
    """returns (char, next_i)"""
    if s[i]=='\\':
        return s[i+1], i+2
    return s[i], i+1

def esc_out(c):
    return pyre.escape(c)

def esc_cls(c):
    if c in '\\]-^[':
        return '\\'+c
    return c

def translate_union(s, i, depth=0):
    """parse union starting at i, return (regex_str, next_i)"""
    alts=[]
    while True:
        part, i = translate_seq(s, i)
        alts.append(part)
        if i < len(s) and s[i]=='|':
            i+=1; continue
        break
    if i < len(s) and s[i]==')':
        i+=1
        return '(?:' + '|'.join(alts) + ')', i
    return '(?:' + '|'.join(alts) + ')', i

def translate_seq(s, i):
    out=[]
    while i < len(s) and s[i] not in '|)':
        atom, i = translate_atom(s, i)
        while i < len(s) and s[i]=='*':
            atom = '(?:'+atom+')*'
            i+=1
        out.append(atom)
    return ''.join(out), i

def translate_atom(s, i):
    c=s[i]
    if c=='(':
        return translate_union(s, i+1)
    if c=='[':
        i+=1
        items=[]
        while i < len(s) and s[i]!=']':
            lo,i = class_char(s,i)
            if i < len(s) and s[i]=='-' and i+1<len(s) and s[i+1]!=']':
                i+=1
                hi,i = class_char(s,i)
                items.append(esc_cls(lo)+'-'+esc_cls(hi))
            else:
                items.append(esc_cls(lo))
        if i<len(s): i+=1
        return '['+''.join(items)+']', i
    if c=='\\':
        return esc_out(s[i+1]), i+2
    return esc_out(c), i+1

ALPHABET = list("abcxyz019.-_ ") + ["\x00","\xe9","\xff"]
def gen_subject():
    return ''.join(random.choice(ALPHABET) for _ in range(random.randint(0,10)))

bad=0; n=0
for trial in range(20000):
    p = gen_pattern()
    try:
        rx = pyre.compile(''.join(translate_union(p,0)[0]) + r'\Z')
    except pyre.error as e:
        print('ORACLE FAIL', repr(p), e); bad+=1; continue
    m = compile_pattern(p)
    for _ in range(3):
        s = gen_subject()
        n+=1
        expected = rx.fullmatch(s) is not None
        got = m.matches(s)
        if expected != got:
            bad+=1
            print('MISMATCH pattern=%r subject=%r expected=%s got=%s' % (p,s,expected,got))
            if bad>10: sys.exit(1)
print('checked %d comparisons, %d mismatches' % (n,bad))
